-- v1.34.0: Luda no longer keeps a balance (pay per service). Every text that described the wallet is rewritten.
-- The previous texts are kept in guides_wallet_backup so they can be restored if a wallet ever comes back.
create table if not exists public.guides_wallet_backup as select * from public.guides where false;
alter table public.guides_wallet_backup enable row level security;
insert into public.guides_wallet_backup select * from public.guides where slug in ('terms', 'refunds', 'aml', 'about', 'privacy', 'help-account-forgot', 'help-account-freeze', 'help-bills-how', 'help-bills-refund', 'help-start-verify', 'help-start-what', 'help-tickets-buy', 'help-wallet-topup', 'help-wallet-pending', 'help-wallet-convert', 'help-wallet-send', 'tip-fees', 'tip-kyc', 'tip-points') and not exists (select 1 from public.guides_wallet_backup);

update public.guides set title = 'Luda Terms & Conditions', intro = 'These terms are an agreement between you and Luda Digital Systems Limited ("Luda", "we"), the company that runs the Luda app and useluda.com. By creating an account or using Luda you agree to them. If we change them, we will ask you to agree again before you continue.', steps = '[{"title": "1. Who we are", "body": "Luda is run by Luda Digital Systems Limited. It is an app for students and people from Africa living in North Cyprus. It offers bus tickets, bill and rent payment help, mobile top-ups, marketplace listings, Flash help requests, community posts and university tools."}, {"title": "2. Your account", "body": "You must be at least 18 and give true details. One person may have only one Luda account. We check every verified ID document and face against all other accounts, so a second account can''t be verified. Extra accounts may be frozen or closed, and rewards, prizes and referral bonuses gained through them will be removed. Keep your password and PIN private; you are responsible for activity on your account. Tell us at once if you think someone else has used it. We may ask you to verify your identity (ID document and selfie) before you can sell on the Market, help on Flash or post."}, {"title": "3. How you pay", "body": "Luda does not keep a balance or hold money for you. You pay for each service at checkout, by card, bank transfer or USSD, through our payment partners (Paystack, or Flutterwave for other currencies). Prices are set in Turkish lira; if you pay in another currency you see the exact amount, including the exchange, before you pay. When the partner confirms your payment, we deliver the service you paid for. We may delay or refuse a payment to check it for fraud, errors or legal reasons."}, {"title": "4. Fees", "body": "Fees are shown on the Fees page (useluda.com/fees and in the app) and on every checkout before you pay. Payment partners may add their own fees. We may change fees for future payments; the price shown when you pay is the one that applies."}, {"title": "5. Bus tickets, bills, rent and top-ups", "body": "Bus tickets appear in the app with a QR code for the driver. Bills and rent are paid by the Luda team on the official site or by bank transfer, and a receipt is added; mobile top-ups may be sent automatically. If we can''t deliver what you paid for, we send the money back to the card or bank account you paid with. Mistakes in the details you typed (like a wrong meter number or IBAN) must be fixed with the biller or the landlord."}, {"title": "6. Market and Flash", "body": "Market listings and Flash requests connect people: buyers pay sellers, and people who post a request pay their helper, directly between themselves. Luda does not take or hold those payments and is not part of that deal. Meet in safe places, check before you pay, and report anything suspicious. Sellers and helpers are responsible for what they offer."}, {"title": "7. Rules everyone follows", "body": "No fraud, fake accounts, money laundering, scams, harassment, hate, adult content, or asking for money in advance for something you haven''t delivered. Posts and messages are checked and limited to keep Luda safe. We may remove content, limit features, freeze or close accounts that break these rules, and report illegal activity to the authorities."}, {"title": "8. Rewards", "body": "XP, points, prizes and referral bonuses are worked out by Luda''s server from real activity and may have monthly limits. Prizes and points become discounts on Luda services; they are not cash and can''t be paid out. Some prizes need a verified identity. Rewards gained by cheating, multiple accounts or fake referrals will be removed."}, {"title": "9. Privacy", "body": "We keep the data needed to run Luda and keep it safe: your profile, identity check results, payments, and messages in support cases. Identity checks are done by our partner Didit. We don''t sell your data. Support photos are visible only to you and the Luda team. Our Privacy notice (useluda.com/privacy) explains more."}, {"title": "10. Information in the app", "body": "University dates, bus times, places and guides are provided to help you and may change; always confirm important dates with the official source. Luda is not your university, bank, landlord or bus company."}, {"title": "11. Limits of our responsibility", "body": "We work hard to keep Luda available and correct, but we can''t promise it will never be interrupted. We are not responsible for losses caused by deals between users (such as Market or Flash payments), by your bank or payment partner, or by you sharing your PIN or password. Nothing in these terms removes rights you have by law."}, {"title": "12. Closing your account", "body": "You can ask the Luda team to close your account at any time. Any service you already paid for and that we haven''t delivered is refunded to your card or bank first. We may close or freeze accounts that break these terms."}, {"title": "13. Refunds, cancellations and chargebacks", "body": "When and how money is returned is explained in our Refund & cancellation policy (useluda.com/refunds), which is part of these terms. If something goes wrong with a payment, contact us first: we answer within 2 business days. If you dispute a payment with your bank (a chargeback) for a service you already received, we may hold your account while we look into it."}, {"title": "14. Identity checks and anti-money-laundering", "body": "We follow our AML & KYC policy (useluda.com/aml). We may ask for more information, limit, hold or refuse a payment, and report suspicious activity to the authorities where the law requires it."}, {"title": "15. Changes and contact", "body": "We may update these terms; the version and date are shown here, and you will be asked to agree to important changes. Questions or complaints: Help, then Message us in the app, or email support@useluda.com. Company details are on useluda.com/about."}]'::jsonb, version = version + 1, updated_at = now(), updated_by = 'luda' where slug = 'terms';
update public.guides set title = 'Refund & cancellation policy', intro = 'This policy explains when and how Luda Digital Systems Limited returns money to you. Luda doesn''t keep a balance: refunds go back to the card or bank account you paid with. To ask for a refund, open Help, then Message us in the app, or email support@useluda.com with your reference (in My payments).', steps = '[{"title": "Payments that don''t go through", "body": "If you were charged but the payment shows as Pending, we check with our payment partner (Paystack or Flutterwave) automatically. If the payment is confirmed we deliver your service; if it wasn''t completed, nothing is delivered and any money taken is returned by the partner to your card or bank, usually within 5–10 business days."}, {"title": "Bus tickets", "body": "Contact us before the travel date to cancel an unused ticket; it is refunded to the card or bank you paid with. Used tickets, and tickets for a date that has passed, are not refunded."}, {"title": "Bills, rent and mobile top-ups", "body": "If the Luda team cannot pay your bill or rent, or a top-up can''t be sent, the full amount and the fee are refunded to the card or bank you paid with, and you are told why. Once a bill is paid and the receipt is added, Luda cannot take it back; mistakes in the details you typed (like a wrong meter number or IBAN) must be fixed with the biller or landlord."}, {"title": "Market and Flash", "body": "Luda doesn''t take payments for Market items or Flash jobs: they are paid directly between people, so Luda can''t refund them. Settle problems with the other person, and report scams to us so we can act on the account."}, {"title": "Fees", "body": "A Luda fee is refunded when the payment it belongs to is refunded in full. Fees charged by payment partners are set by the partner and may not be returned by them."}, {"title": "Discounts", "body": "If a payment that used a reward discount is refunded or not completed, the discount goes back to your account."}, {"title": "Chargebacks", "body": "Please contact us before disputing a payment with your bank. If you open a chargeback for a service you already received, we may hold your account while we look into it."}, {"title": "How long it takes", "body": "We answer refund requests within 2 business days. We start automatic refunds as soon as we know a service can''t be delivered; the time for the money to reach you depends on the payment partner and your bank, usually 5–10 business days. You can follow every refund in My payments."}]'::jsonb, updated_at = now(), updated_by = 'luda' where slug = 'refunds';
update public.guides set title = 'AML & KYC policy', intro = 'Luda Digital Systems Limited works to stop fraud, money laundering and the financing of crime on Luda. This policy explains the checks we do and what we may do when something looks wrong.', steps = '[{"title": "Knowing our customers", "body": "Every account needs a real name, an email address and a payment PIN. Before you can sell on the Market, help on Flash or post, you must verify your identity with an official ID document and a live selfie. Checks are done by our partner Didit, or by the Luda team for documents sent to us."}, {"title": "One account per person", "body": "Each person may have only one Luda account. ID documents and faces are compared with other verified accounts, and extra accounts are frozen."}, {"title": "No stored balances", "body": "Luda does not hold money for customers. Every payment is for a specific service (a bus ticket, a bill, rent or a mobile top-up), is paid through our licensed payment partners, and any refund goes back to the same card or bank account."}, {"title": "Limits", "body": "Payments have daily limits set by our server. Rewards are discounts on Luda services, never cash."}, {"title": "Monitoring", "body": "Our server records every payment and refund. We watch for unusual activity, such as many accounts on one device, payments that don''t match, or patterns linked to scams."}, {"title": "What we may do", "body": "We may ask for more information or documents, delay or refuse a payment, limit or freeze an account, and close accounts used for fraud. Where the law requires it, we report suspicious activity to the authorities, and we may not be allowed to tell you."}, {"title": "Not allowed on Luda", "body": "Money laundering, fraud, scams, using someone else''s identity, card or account, buying or selling accounts, paying for illegal goods or services, and asking people to pay outside Luda for Luda services."}, {"title": "Records", "body": "We keep identity check results and payment records for as long as the law requires, including after an account is closed."}, {"title": "Reporting a concern", "body": "To report suspicious activity, use Report a scam in Help, or email support@useluda.com."}]'::jsonb, updated_at = now(), updated_by = 'luda' where slug = 'aml';
update public.guides set title = 'About Luda', intro = 'Luda is an all-in-one app for African students and families living in North Cyprus. It is run by Luda Digital Systems Limited.', steps = '[{"title": "What we offer", "body": "• Girne ⇄ Lefkoşa bus tickets.\n• Bill payments (electricity, water, gas, internet, mobile) and rent, paid by the Luda team on the official sites or by bank transfer.\n• Mobile top-ups.\n• Marketplace listings and Flash help requests, paid directly between people.\n• Free community, housing, jobs and university tools."}, {"title": "Prices", "body": "Creating an account is free and there are no monthly fees. Prices are in Turkish lira and each service shows its full price, with any fee, before you pay; the full list is on the Fees page. Bus tickets cost ₺250 single and ₺450 return."}, {"title": "How you pay", "body": "Luda doesn''t keep a balance. You pay for each service at checkout by card, bank transfer or USSD through Paystack, or through Flutterwave for other currencies. You get a receipt for every payment in My payments."}, {"title": "When you get it", "body": "Bus tickets appear in the app straight after payment, with a QR code for the driver. Bills and rent are paid within the time shown when you pay, usually within 2 hours during working hours. If we can''t deliver, the money goes back to your card or bank. Market items and Flash jobs are arranged between the people involved."}, {"title": "Contact us", "body": "Help with your account or a payment: support@useluda.com\nGeneral questions: hello@useluda.com\nIn the app: Help, then Message us\nWe answer within 2 business days."}, {"title": "Company", "body": "Luda Digital Systems Limited"}]'::jsonb, updated_at = now(), updated_by = 'luda' where slug = 'about';
update public.guides set title = 'Privacy notice', intro = 'Luda Digital Systems Limited ("Luda") is responsible for the personal data used in the Luda app and on useluda.com. This notice explains what we collect, why, who we share it with and your choices.', steps = '[{"title": "What we collect", "body": "Your name, email, username, phone (if you add it), country, university, the posts and messages you send in Luda, your payments and the services you bought, and the ID document and selfie checked by our ID partner. Card and bank details are entered on our payment partners'' pages; Luda never sees your full card number."}, {"title": "Why", "body": "To take payments and deliver the services you buy, send refunds, confirm who you are, prevent fraud and scams, keep the community safe, and help you when you contact us."}, {"title": "Who we share it with", "body": "Only the partners needed to run the service: payment providers (Paystack, Flutterwave), our ID check partner (Didit), our email provider and our hosting. We may also share information when the law requires it, for example with the police or a regulator. We never sell your data."}, {"title": "What stays on your phone", "body": "Your theme, language, drafts and timetable photos (read on your phone, never uploaded)."}, {"title": "How long we keep it", "body": "Account and payment records are kept for as long as the law requires for financial records, even after you close your account. Photos you send to support are kept only as long as the case needs them."}, {"title": "How we protect it", "body": "Data travels over encrypted connections. Your PIN and sign-in code are stored only as secure hashes. ID photos and support files are private and visible only to the Luda team members who need them."}, {"title": "Your choices", "body": "You can download your data in Security, turn notifications on or off, and ask the Luda team to close your account. Some records must be kept for legal and anti-fraud reasons. Questions about your data: support@useluda.com."}]'::jsonb, updated_at = now(), updated_by = 'luda' where slug = 'privacy';
update public.guides set title = 'I forgot my password or sign-in code', intro = 'On the sign-in screen tap ''Forgot password?'' and we''ll email you a code. Forgot your 4-digit payment PIN? Security → Payment PIN → ''Forgot your PIN?''.', updated_at = now(), updated_by = 'luda' where slug = 'help-account-forgot';
update public.guides set title = 'I think someone else is using my account', intro = 'Go to Security → Freeze my payments straight away, then change your password and check Recent sign-ins. Open a request so the team can help you.', updated_at = now(), updated_by = 'luda' where slug = 'help-account-freeze';
update public.guides set title = 'How does bill pay work?', intro = 'Choose the bill, type the details exactly as they appear on your bill and see the price: the amount plus the service fee (₺10 up to ₺1,000, ₺20 above). Pay by card, bank transfer or USSD. The Luda team pays it on the official site and uploads the receipt, usually within 2 hours between 09:00 and 19:00. If we can''t pay it, everything goes back to your card or bank.', updated_at = now(), updated_by = 'luda' where slug = 'help-bills-how';
update public.guides set title = 'Why was my bill refunded?', intro = 'If the team can''t pay it (for example the account number isn''t found), the full amount and the fee go back to the card or bank you paid with, and you see the reason in My payments. Check the details and try again.', updated_at = now(), updated_by = 'luda' where slug = 'help-bills-refund';
update public.guides set title = 'Why do I need to verify my ID?', intro = 'You can look around and pay for services without an ID check. Verifying your ID (a photo of your document and a quick selfie) unlocks selling on Market, helping on Flash, posting and some prizes. It keeps scammers and fake accounts out. You get 2 tries a day.', updated_at = now(), updated_by = 'luda' where slug = 'help-start-verify';
update public.guides set title = 'What can I do with Luda?', intro = 'Luda is one app for life in North Cyprus: Girne ⇄ Lefkoşa bus tickets, bills and rent paid for you by the Luda team, mobile top-ups, Market listings, Flash help requests, rooms and jobs, university dates and places near you. You pay for each service when you use it; Luda doesn''t keep a balance.', updated_at = now(), updated_by = 'luda' where slug = 'help-start-what';
update public.guides set title = 'How do bus tickets work?', intro = 'Transport → Girne ⇄ Lefkoşa. Pick the trip, see the price and pay by card, bank transfer or USSD, with no booking fee. Your ticket''s QR code changes every 30 seconds, so screenshots don''t work. Show it to the driver: a single works once, a return once each way.', updated_at = now(), updated_by = 'luda' where slug = 'help-tickets-buy';
update public.guides set title = 'How do I pay for a service?', intro = 'Pick what you need (bus ticket, bill, rent or mobile top-up) and tap Continue to payment. You see the exact price first. Pay in Naira with Paystack (card, bank transfer or USSD), or in USD, GHS, KES, UGX, ZMW or XAF with Flutterwave. Luda doesn''t keep a balance, so there''s nothing to top up.', updated_at = now(), updated_by = 'luda' where slug = 'help-wallet-topup';
update public.guides set title = 'I paid but it still says pending', intro = 'Most payments are confirmed within a minute. If it still says Pending, open My payments again: we re-check with the payment provider automatically. If it''s not done after an hour, open the payment in My payments and tap ''Report a problem'', so the team can check it with the reference.', updated_at = now(), updated_by = 'luda' where slug = 'help-wallet-pending';
update public.guides set title = 'Can I pay in Naira?', intro = 'Yes. Prices are in lira, and the checkout shows the exact Naira amount before you pay (it includes a 1% exchange margin). You can also pay in USD, GHS, KES, UGX, ZMW or XAF.', updated_at = now(), updated_by = 'luda' where slug = 'help-wallet-convert';
update public.guides set title = 'How do refunds work?', intro = 'If Luda can''t deliver what you paid for, we refund it automatically to the card or bank account you paid with, usually within 5–10 business days depending on your bank. You can follow it in My payments. Any reward discount you used comes back too.', updated_at = now(), updated_by = 'luda' where slug = 'help-wallet-send';
update public.guides set title = 'About fees', intro = 'Every Luda fee is set by our server and shown before you pay. Payment partners may add their own small fee at checkout. There are no monthly fees.', updated_at = now(), updated_by = 'luda' where slug = 'tip-fees';
update public.guides set title = 'Why we check your ID', intro = 'One real person, one account. Checking your ID (document + selfie) keeps scammers out, and unlocks selling, Flash jobs, posting and some prizes. Your ID is checked by our partner Didit; you get 2 tries a day.', updated_at = now(), updated_by = 'luda' where slug = 'tip-kyc';
update public.guides set title = 'Points, XP and prizes', intro = 'XP and points come from what you really do in Luda, worked out on our server. Verified accounts can turn points into discounts on Luda services. Prizes have a monthly budget; after that you get points instead.', updated_at = now(), updated_by = 'luda' where slug = 'tip-points';
